import{_ as a,o as s,c as t,a2 as o}from"./chunks/framework.BvlN9b-o.js";const g=JSON.parse('{"title":"发布自己的教程站点","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/publish-docs.md","filePath":"getting-started/publish-docs.md"}'),i={name:"getting-started/publish-docs.md"};function d(c,e,n,r,p,l){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="发布自己的教程站点" tabindex="-1">发布自己的教程站点 <a class="header-anchor" href="#发布自己的教程站点" aria-label="Permalink to &quot;发布自己的教程站点&quot;">​</a></h1><p>仓库 Markdown 是唯一可编辑来源。<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/61c599464afc152695d7932084528b9cdb89c59b/docs/site.json" target="_blank" rel="noreferrer">站点清单</a>决定公开页面；源码片段、API 与配置参考从实现生成。<code>apps/docs/.generated</code> 和构建产物不提交到源码分支。</p><h2 id="首次启用-github-pages" tabindex="-1">首次启用 GitHub Pages <a class="header-anchor" href="#首次启用-github-pages" aria-label="Permalink to &quot;首次启用 GitHub Pages&quot;">​</a></h2><p>以下步骤面向有仓库管理权限的维护者。先把源码提交并推送到自己的 GitHub 仓库，确认 <code>origin</code> 指向它，将 <code>docs/site.json</code> 的 <code>repository</code> 改为自己的 <code>owner/repository</code>。源码链接包含当前提交 SHA，因此必须在提交后重新构建。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish-docs.mjs</span></span></code></pre></div><p>发布脚本把静态文件提交到独立的 <code>gh-pages</code> 分支，不切换当前源码分支，也不修改当前暂存区。随后在 GitHub 的 <strong>Settings → Pages → Build and deployment</strong> 中选择 <strong>Deploy from a branch</strong>，分支为 <code>gh-pages</code>，目录为 <code>/ (root)</code>，并保存。公共仓库可使用此方式；其他可见性取决于 GitHub 账号方案。</p><p>本机安装并登录 GitHub CLI 后，请求构建并验证线上结果：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish-docs.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --request-build</span></span></code></pre></div><p>命令会检查 Pages 配置，显式请求构建，确认构建对应刚发布的静态产物提交，并读取线上首页检查源码版本。在五分钟内未完成时会失败退出；推送成功本身不代表网页已经可访问。</p><h2 id="后续自动发布" tabindex="-1">后续自动发布 <a class="header-anchor" href="#后续自动发布" aria-label="Permalink to &quot;后续自动发布&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/61c599464afc152695d7932084528b9cdb89c59b/.github/workflows/ci.yml" target="_blank" rel="noreferrer">CI 工作流</a>在 PR 中运行 <code>just check</code> 并保存文档产物。源码合并到 <code>main</code>、检查通过后，发布任务将同一份产物推送到 <code>gh-pages</code>，并使用 <code>contents: write</code> 和 <code>pages: write</code> 权限显式请求 Pages 构建。</p><p>GitHub Actions 使用 <code>GITHUB_TOKEN</code> 推送分支不会自动触发 Pages 构建，因此不能省略 <code>--request-build</code>。首次 Pages 设置仍需管理员完成，CI 不尝试修改仓库管理设置。</p><p>默认地址为 <code>https://&lt;owner&gt;.github.io/&lt;repository&gt;/</code>。站点路径由仓库名决定；自定义域名或非默认路径可通过 <code>DOCS_BASE</code> 调整构建路径。</p><hr><p>源码版本：<code>61c599464afc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/61c599464afc152695d7932084528b9cdb89c59b/docs/getting-started/publish-docs.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,15)])])}const b=a(i,[["render",d]]);export{g as __pageData,b as default};
